  const left=side<0,shoulder=[side*(left?.285:.265),-.045,.44+(left?.075:-.01)+weight];
  const swing=step*side*(running?.20:.07),hip=[side*.15,-.025,-.16],knee=[side*.18,swing,-.57+weight],ankle=[side*.20,-swing*.42,-.90];
